<div class="page-title"><div><h2>دفترکل <?= e($accountUser['full_name'] ?? '') ?></h2><p class="text-muted">مانده فعلی: <strong><?= money_toman($balance ?? 0) ?></strong></p></div></div>
<section class="card mb-4"><div class="card-header"><h3>ثبت سند حسابداری</h3></div><form method="post" action="<?= e(url('plugin/accounting/ledger/post')) ?>" class="form-grid four"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int) ($accountUser['id'] ?? 0) ?>"><label>نوع سند<select name="entry_type" required><option value="bonus">پاداش</option><option value="expense">هزینه قابل پرداخت</option><option value="deduction">کسر از حساب</option><option value="payment">پرداخت وجه به کاربر</option><option value="receipt">دریافت وجه از کاربر</option><option value="manual_increase">افزایش دستی</option><option value="manual_decrease">کاهش دستی</option></select></label><label>مبلغ<input name="amount" inputmode="numeric" required></label><label>روش<input name="method"></label><label>شماره پیگیری<input name="tracking" dir="ltr"></label><label class="full">شرح<input name="description" required></label><div class="full"><button class="btn btn-primary" type="submit">ثبت سند</button></div></form></section>
<section class="card"><div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>شماره</th><th>تاریخ</th><th>نوع</th><th>اثر بر مانده</th><th>مبلغ</th><th>مانده پس از عملیات</th><th>شرح</th><th>عملیات</th></tr></thead><tbody><?php foreach (($entries ?? []) as $entry): ?><tr><td dir="ltr"><?= e($entry['entry_number'] ?? '-') ?></td><td><?= e(jdatetime($entry['created_at'])) ?></td><td><?= e($entry['entry_type']) ?></td><td class="<?= $entry['direction'] === 'increase' ? 'proma-accounting-positive' : 'proma-accounting-negative' ?>"><?= $entry['direction'] === 'increase' ? 'افزایش مانده' : 'کاهش مانده' ?></td><td><?= money_toman($entry['amount']) ?></td><td><?= money_toman($entry['balance_after']) ?></td><td><?= e($entry['description']) ?></td><td><?php if (($entry['entry_type'] ?? '') !== 'reversal' && empty($entry['reversed_entry_id'])): ?><form method="post" action="<?= e(url('plugin/accounting/ledger/reverse/' . (int) $entry['id'])) ?>" class="accounting-reverse-form"><?= csrf_field() ?><input name="reason" required placeholder="علت معکوس‌سازی"><button class="btn btn-sm btn-light" type="submit">ثبت معکوس</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (empty($entries)): ?><tr><td colspan="8" class="empty">هنوز سندی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div><?= render_pagination($pagination ?? [], static function ($page) use ($accountUser) { return url('plugin/accounting/ledger/' . (int) ($accountUser['id'] ?? 0), ['page' => $page]); }) ?></section>
